package middleware

import (
	"net/http"

	"gitlab.opencode.de/open-code/badgebackend/badge-api/pkg/config"
)

func LockConfigRefreshMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		config.ConfigRefreshRWMutex.RLock()
		defer config.ConfigRefreshRWMutex.RUnlock()
		next.ServeHTTP(w, r)
	})
}
